		-- {24911, 24912, 24913, 24914}
		introduction_th = 'ฮีโร่โบราณที่สุดในประวัติศาสตร์มนุษย์ มีสายเลือดเทพสามส่วนสองและสายเลือดมนุษย์หนึ่งส่วนสาม ด้วยนิสัยหยิ่งยโส เคยเป็นเผด็จการที่คิดว่าไม่มีใครชนะได้',
		introduction = 'The oldest hero in human history, with two-thirds divine blood and one-third human blood. With an arrogant personality, he was once a tyrant who believed no one could defeat him.',
		introduction_vn = 'Anh hùng cổ xưa nhất trong lịch sử loài người, mang hai phần ba dòng máu thần thánh và một phần ba dòng máu con người. Với tính cách kiêu ngạo, ông từng là một bạo chúa tự cho rằng không ai có thể đánh bại mình.',
		introduction_in = 'Pahlawan tertua dalam sejarah umat manusia, memiliki dua pertiga darah ilahi dan sepertiga darah manusia. Dengan sifat sombong, dia dulunya adalah seorang tiran yang percaya tidak ada yang bisa mengalahkannya.',
		introduction_en = 'The oldest hero in human history, with two-thirds divine blood and one-third human blood. With an arrogant personality, he was once a tyrant who believed no one could defeat him.',
		introduction_ph = 'Pinakamahusay na bayani sa kasaysayan ng tao, may dalawang-katlong dugong diyos at isang-katlong dugong tao. Sa pagiging mayabang, siya ay isang tirano na naniniwala na walang makakapagpatalo sa kanya.',
		introduction_ma = 'Pahlawan tertua dalam sejarah manusia, dengan dua pertiga darah ilahi dan sepertiga darah manusia. Dengan sikap sombong, dia pernah menjadi seorang tiran yang percaya tiada siapa yang dapat mengalahkannya.',
