		fetterList = {80041, 80042, 80043, 80044},
		introduction_th = 'Kocho Shinobu – เสาหลักแมลงที่กลายเป็นซากศพพลังลดลง แต่ยังทำให้ศัตรูหวาดกลัวด้วยดาบเคลือบพิษ ภายใต้รอยยิ้มอ่อนโยนคือความมุ่งมั่นในการล่ายักษ์ที่ไม่อาจสั่นคลอน',
		introduction = 'A young swordsman of the Demon Slayer Corps, Kanao stands out for her calm demeanor and gentle eyes hiding immense power. Though quiet and rarely showing emotion, she possesses exquisite speed and the elegant Flower Breathing swordsmanship.',
		introduction_vn = 'Một kiếm sĩ trẻ thuộc Sát Quỷ Đội, Kanao nổi bật với sự điềm tĩnh và đôi mắt dịu dàng ẩn chứa sức mạnh khôn lường. Dù trầm lặng và ít khi bộc lộ cảm xúc, cô lại sở hữu tốc độ và kỹ năng kiếm pháp Hoa Hơi tuyệt mỹ',
		introduction_in = 'Seorang pendekar muda dari Korps Pembasmi Iblis, Kanao menonjol dengan ketenangan dan mata lembut yang menyimpan kekuatan besar. Meskipun pendiam dan jarang menunjukkan emosi, ia memiliki kecepatan dan ilmu pedang Flower Breathing yang indah.',
		introduction_en = 'A young swordsman of the Demon Slayer Corps, Kanao stands out for her calm demeanor and gentle eyes hiding immense power. Though quiet and rarely showing emotion, she possesses exquisite speed and the elegant Flower Breathing swordsmanship.',
		introduction_ph = 'Isang batang mandirigmang tabak ng Demon Slayer Corps, namumukod-tangi si Kanao sa kanyang kalmado at banayad na mga mata na nagtatago ng malaking lakas. Bagamat tahimik at bihirang ipakita ang damdamin, taglay niya ang kahanga-hangang bilis at marilag na Flower Breathing na kasanayan sa tabak.',
		introduction_ma = 'Seorang pendekar muda daripada Kor Demon Slayer, Kanao menonjol dengan sikap tenang dan mata lembut yang menyembunyikan kuasa besar. Walaupun pendiam dan jarang menunjukkan emosi, dia memiliki kelajuan dan seni pedang Flower Breathing yang indah.',
