		fetterList = {80051, 80052, 80053, 80054},
		introduction_th = 'นักดาบหนุ่มของหน่วยพิฆาตอสูร Kanao โดดเด่นด้วยความเยือกเย็นและสายตาอ่อนโยนที่ซ่อนพลังมหาศาล แม้จะเงียบและไม่ค่อยแสดงอารมณ์ เธอมีความเร็วและทักษะดาบลมหายใจดอกไม้ที่งดงาม',
		introduction = 'Kyojuro Rengoku is a powerful Hashira of the Demon Slayer Corps. Before succeeding his father, he trained himself through three Flame Breathing scrolls and became an exceptional swordsman. He once avenged nine slain Demon Slayers and single-handedly defeated Lower Rank Two, Hairo',
		introduction_vn = 'Kyojuro Rengoku là một Hashira mạnh mẽ của Sát Quỷ Đoàn. Trước khi kế nhiệm cha mình, anh đã tự luyện tập qua ba cuốn sách Thở Lửa và trở thành kiếm sĩ xuất sắc. Anh từng báo thù cho 9 Sát quỷ bị giết và một mình đánh bại Hạ cấp Hai Hairo.',
		introduction_in = 'Kyojuro Rengoku adalah Hashira yang kuat dari Korps Pembasmi Iblis. Sebelum menggantikan ayahnya, ia melatih dirinya melalui tiga gulungan Pernapasan Api dan menjadi pendekar pedang luar biasa. Ia pernah membalas dendam untuk 9 Pembasmi Iblis yang terbunuh dan seorang diri mengalahkan Iblis Peringkat Bawah Dua, Hairo.',
		introduction_en = 'Kyojuro Rengoku is a powerful Hashira of the Demon Slayer Corps. Before succeeding his father, he trained himself through three Flame Breathing scrolls and became an exceptional swordsman. He once avenged nine slain Demon Slayers and single-handedly defeated Lower Rank Two, Hairo',
		introduction_ph = 'Si Kyojuro Rengoku ay isang makapangyarihang Hashira ng Demon Slayer Corps. Bago sundan ang kanyang ama, sinanay niya ang sarili sa tatlong scroll ng Flame Breathing at naging isang pambihirang mandirigmang tabak. Minsan niyang ipinaghiganti ang siyam na Demon Slayer na pinaslang at mag-isa niyang tinalo ang Lower Rank Two na si Hairo.',
		introduction_ma = 'Kyojuro Rengoku ialah seorang Hashira yang kuat dari Kor Demon Slayer. Sebelum menggantikan bapanya, dia melatih dirinya melalui tiga gulungan Nafas Api dan menjadi pendekar pedang yang hebat. Dia pernah membalas dendam untuk 9 pembasmi iblis yang terbunuh dan seorang diri mengalahkan Iblis Peringkat Bawah Dua, Hairo.',
