		fetterList = {80091, 80092, 80093, 80094},
		introduction_th = 'เบื้องหลังรูปลักษณ์ที่สง่างามคือวิญญาณที่เคยถูกความมืดกลืน Tamayo – หมอปีศาจลึกลับ เลือกทางแห่งการเยียวยาในโลกที่เต็มไปด้วยเลือด เธอใช้การแพทย์แทนอาวุธ ใช้เลือดแทนดาบ เงียบ ๆ ต่อต้าน Muzan ด้วยปัญญาและความเมตตา ทุกย่างก้าวเป็นเครื่องพิสูจน์ความอ่อนโยนโดยไม่อ่อนแอ และความเกลียดชังโดยไม่ต้องตะโกน',
		introduction = 'Dracule Mihawk — the world\'s strongest swordsman, wielding the sword Yoru (Black Sword – one of the 12 Supreme Grade blades), and capable of using both Observation Haki and Armament Haki.',
		introduction_vn = 'Dracule Mihawk — Thợ Kiếm mạnh nhất thế giới, sở hữu thanh kiếm Yoru (Black Sword – một trong 12 Supreme Grade blades), và khả năng sử dụng cả Observation Haki (Haki quan sát) và Armament Haki (Haki vũ trang)',
		introduction_in = 'Dracule Mihawk — pendekar pedang terkuat di dunia, memiliki pedang Yoru (Black Sword – salah satu dari 12 bilah Tingkat Tertinggi), dan mampu menggunakan baik Observation Haki maupun Armament Haki.',
		introduction_en = 'Dracule Mihawk — the world\'s strongest swordsman, wielding the sword Yoru (Black Sword – one of the 12 Supreme Grade blades), and capable of using both Observation Haki and Armament Haki.',
		introduction_ph = 'Si Dracule Mihawk — ang pinakamalakas na mandirigmang tabak sa mundo, may hawak na espada na Yoru (Black Sword – isa sa 12 Supreme Grade blades), at may kakayahang gumamit ng parehong Observation Haki at Armament Haki.',
		introduction_ma = 'Dracule Mihawk — pendekar pedang terkuat di dunia, memiliki pedang Yoru (Black Sword – salah satu daripada 12 bilah Gred Tertinggi), dan mampu menggunakan kedua-dua Observation Haki dan Armament Haki.',
